mapper.select:
SELECT id, tenant_id, scope_code, actor_id, idempotency_key, request_digest,
       status, resource_type, resource_key, response_payload, version,
       creator, create_time, updater, update_time, deleted
FROM plt_idempotency_record
WHERE tenant_id = #{query.tenantId}
  AND scope_code = #{query.scopeCode}
  AND actor_id = #{query.actorId}
  AND idempotency_key = #{query.idempotencyKey}
  AND deleted = 0
